update BOK_STAT_DET_POSIITON
set TDY_LOSS_AMT = #{tdyLossamt,jdbcType=DECIMAL},
    TDY_LOSS_AMT_B = #{tdyLossamtB,jdbcType=DECIMAL},
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
  and HAPPEN_DATE = #{happenDate,jdbcType=DATE}
  and BOOK_DATE = #{bookDate,jdbcType=DATE}
  and BOK_DETAIL_ID = #{bokDetailId,jdbcType=VARCHAR}
